    expectTrue(fuse::profiler::wouldSkipBeginAsyncFlow(nullptr),
               "wouldSkipBeginAsyncFlow true for null name");
    expectTrue(fuse::profiler::wouldSkipBeginAsyncFlow(""),
               "wouldSkipBeginAsyncFlow true for empty name");
