void testWouldSkipHelpers() {
    resetState();
    fuse::platform::registerMainThread();

    expectTrue(fuse::profiler::wouldSkipProfileScope(nullptr), "wouldSkipProfileScope true for null name");
    expectTrue(fuse::profiler::wouldSkipProfileScope(""), "wouldSkipProfileScope true for empty name");
    expectTrue(!fuse::profiler::wouldSkipProfileScope("valid_scope"),
               "wouldSkipProfileScope false for valid name");
    expectTrue(!fuse::profiler::wouldSkipChromeTraceExport(),
               "wouldSkipChromeTraceExport false when profiler enabled");
    expectTrue(!fuse::profiler::wouldSkipChromeTraceExportSafely(),
               "wouldSkipChromeTraceExportSafely false on empty balanced buffer");

    const fuse::u32 flowId = fuse::profiler::nextFlowId();
    expectTrue(fuse::profiler::wouldSkipBeginAsyncFlow(nullptr, flowId),
               "wouldSkipBeginAsyncFlow true for null name");
    expectTrue(fuse::profiler::wouldSkipEndAsyncFlow("orphan", flowId),
               "wouldSkipEndAsyncFlow true for orphan finish");
    expectTrue(fuse::profiler::wouldSkipCounter(nullptr), "wouldSkipCounter true for null track");
    expectTrue(fuse::profiler::wouldSkipCounter(""), "wouldSkipCounter true for empty track");
    expectTrue(!fuse::profiler::wouldSkipCounter("valid_counter"),
               "wouldSkipCounter false for valid track");

    fuse::profiler::setEnabled(false);
    expectTrue(fuse::profiler::wouldSkipProfileScope("ignored"),
               "wouldSkipProfileScope true when profiler disabled");
    expectTrue(fuse::profiler::wouldSkipBeginAsyncFlow("ignored", flowId),
               "wouldSkipBeginAsyncFlow true when profiler disabled");
    expectTrue(fuse::profiler::wouldSkipCounter("ignored"),
               "wouldSkipCounter true when profiler disabled");
    expectTrue(fuse::profiler::wouldSkipChromeTraceExport(),
               "wouldSkipChromeTraceExport true when profiler disabled");

    fuse::profiler::setEnabled(true);
    FUSE_PROFILE_ASYNC_FLOW_BEGIN("skip_flow", flowId);
    expectTrue(!fuse::profiler::wouldSkipEndAsyncFlow("skip_flow", flowId),
               "wouldSkipEndAsyncFlow false after valid begin");
    FUSE_PROFILE_ASYNC_FLOW_END("skip_flow", flowId);

    {
        FUSE_PROFILE_SCOPE("skip_scope");
    }
    expectTrue(!fuse::profiler::wouldSkipChromeTraceExportSafely(),
               "wouldSkipChromeTraceExportSafely false for balanced trace");
    expectTrue(fuse::profiler::wouldSkipProfileScope(nullptr) ==
                   !fuse::profiler::preflightProfileScope(nullptr).canEnter,
               "wouldSkipProfileScope agrees with preflight canEnter");
    expectTrue(fuse::profiler::wouldSkipBeginAsyncFlow("flow", flowId) ==
                   !fuse::profiler::preflightBeginAsyncFlow("flow", flowId).canBegin,
               "wouldSkipBeginAsyncFlow agrees with preflight canBegin");
}

